import fs from 'node:fs';import assert from 'node:assert/strict';const dir='docs/audits/jpn_dp4_artist_review_20261119',before=JSON.parse(fs.readFileSync(`${dir}/live-identity-species-20261119.json`)),after=JSON.parse(fs.readFileSync(`${dir}/live-identity-species-postfour-20261119.json`)),plan=JSON.parse(fs.readFileSync('docs/audits/jpn_dp4_artist_review_20261119/four-subject-execution-plan-20261119.json'));assert.equal(before.sanity.read_only,'on');assert.equal(after.sanity.read_only,'on');const results=[];for(const r of plan.rows){const oldParent=before.current.find(x=>x.id===r.parent_before.id),newParent=after.current.find(x=>x.id===r.parent_before.id);assert.deepEqual(newParent,oldParent);const identities=after.identities.filter(x=>x.identity.card_print_id===r.parent_before.id&&x.identity.is_active);assert.equal(identities.length,1);const identity=identities[0].identity;assert.deepEqual(identity.identity_payload.card_name_en_candidates,[r.expected_species.en]);assert.deepEqual(identity.identity_payload.normalized_family_name_candidates,[r.expected_species.en.toLowerCase()]);assert.equal(identity.identity_key_hash,r.identity_before.identity_key_hash);const links=after.species.filter(x=>x.link.card_print_id===r.parent_before.id);const old=links.find(x=>x.link.id===r.old_link_before.id),added=links.find(x=>x.link.id===r.new_link_id);assert.equal(links.length,2);assert.equal(old?.link.active,false);assert.equal(old?.link.counts_for_completion,false);assert.deepEqual(old?.link.evidence,r.old_link_before.evidence);assert.equal(added?.link.active,true);assert.equal(added?.link.role,'primary');assert.equal(added?.link.counts_for_completion,true);assert.equal(added?.species.national_dex_number,r.expected_species.dex);results.push({gv_id:r.gv_id,expected:r.expected_species.en,dex:r.expected_species.dex,old_link_inactive:true,new_link_active:true,identity_hash_unchanged:true,parent_readback_unchanged:true});}const out={version:'JPN_DP4_SUBJECT_INDEPENDENT_READBACK_V1',verified_at:new Date().toISOString(),before_capture:before.captured_at,after_capture:after.captured_at,status:'passed',scope:'Separate read-only snapshots of four parent, identity and species records; source/protected-state verification is retained in the writer receipt.',results};if(!process.argv.includes('--check'))fs.writeFileSync('docs/audits/jpn_dp4_artist_review_20261119/independent-four-subject-readback-20261119.json',JSON.stringify(out,null,2)+'\n',{flag:'wx'});console.log(JSON.stringify(out));
